import { useEffect, useState, type ReactNode } from 'react';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  dateLabel,
  fetchPanelSummary,
  latestOfferLine,
  latestQueryLine,
  metricLabel,
  subtitleLabel,
  type PanelSummary,
} from '../../lib/panel';
import styles from './Panel.module.css';

/**
 * PANEL-01 · Mi Panel — dashboard de entrada tras login.
 *
 * =============================================================================
 * DECISIONES QUE ESTA IMPLEMENTACIÓN TOMA Y POR QUÉ
 * =============================================================================
 *
 * 1 · TRES MÉTRICAS VAN CON GUION, NO CON CERO.
 *    `lib/panel.ts` devuelve `null` para visitas (30d), hilos sin leer y
 *    favoritos del mes porque no tienen fuente (no hay tabla de visitas, no hay
 *    registro de lectura y la RLS de favoritos devolvería 0 en silencio).
 *    `metricLabel(null)` pinta '—'. Un 0 afirmaría "he mirado y no hay ninguno",
 *    y eso sería falso. La tarjeta Hilos lo dice además en su línea de detalle,
 *    igual que INV-01 dice "sin instrumentar en el MVP".
 *
 * 2 · FAVORITOS RECIBIDOS ES UN `<button disabled>`, NO UN DIV Y NO NAVEGA.
 *    La spec §4.6 dice que navega a DIR-01/DIR-02, y DIR no existe en el MVP.
 *    Un div clicable violaría RNG-PANEL-03 y el teclado; un botón que navega a
 *    una pantalla que no existe mentiría. Deshabilitado con `title` es el mismo
 *    patrón que el botón de subida de INV-01: se ve dónde estará y se dice por
 *    qué todavía no.
 *
 * 3 · LAS LÍNEAS DE DETALLE DE OFERTAS Y CONSULTAS SE IMPORTAN, NO SE
 *    REESCRIBEN. `latestOfferLine` y `latestQueryLine` son lógica pura
 *    entregada y probada en `lib/panel.ts`; el componente las pinta tal cual.
 *
 * 4 · MIENTRAS CARGA NO HAY CAJAS. Un esqueleto con el número a medias puede
 *    leerse como dato; el spec quiere que las cajas refuercen "dato actualizado",
 *    así que no se pintan hasta que `fetchPanelSummary` resuelve.
 *
 * 5 · EL RELOJ SE ESTABILIZA POR VALOR, NO POR IDENTIDAD.
 *    El padre puede construir un `Date` nuevo en cada render; depender del
 *    objeto relanzaría la consulta sin necesidad. Se deriva `nowKey` (número) y
 *    el efecto depende de él: mismo instante, misma consulta.
 */

const EYEBROW = 'Panel · PANEL-01';
const TITLE = 'Mi Panel';
const LOADING = 'Cargando panel…';
const THREADS_UNAVAILABLE = 'Sin registro de lectura en el MVP';
const FAVORITES_DISABLED_TITLE =
  'El directorio de empresas (DIR-01/DIR-02) está fuera del alcance del MVP';

interface Props {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  onNavigate: (screen: 'Vendiendo' | 'Comprando' | 'Inventario' | 'Hilos') => void;
}

export function Panel({ profile, now, onNavigate }: Props) {
  const [summary, setSummary] = useState<PanelSummary | null>(null);
  const [error, setError] = useState<string | null>(null);
  const nowKey = now?.getTime();

  useEffect(() => {
    let cancelled = false;
    setSummary(null);
    setError(null);
    const query =
      nowKey === undefined
        ? { orgId: profile.orgId }
        : { orgId: profile.orgId, now: new Date(nowKey) };
    fetchPanelSummary(query)
      .then((s) => {
        if (!cancelled) setSummary(s);
      })
      .catch((e) => {
        if (!cancelled) setError(`No se ha podido cargar el panel: ${errorMessage(e)}`);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, nowKey]);

  return (
    <div className={styles.body}>
      <div className={styles.inner}>
        <div className={styles.eyebrow}>{EYEBROW}</div>
        <h1 className={styles.title}>{TITLE}</h1>
        <p className={styles.sub}>{subtitleLabel(profile.fullName, profile.email, now)}</p>

        {error !== null ? (
          <div className={styles.error} role="alert">
            {error}
          </div>
        ) : summary === null ? (
          <p className={styles.loading} aria-busy="true">
            {LOADING}
          </p>
        ) : (
          <div className={styles.grid}>
            <SummaryCard
              icon="ti-tag"
              title="Ofertas"
              testId="card-offers"
              onClick={() => onNavigate('Vendiendo')}
            >
              <div className={styles.num}>{metricLabel(summary.offers.pending)}</div>
              <div className={styles.label}>pendientes de respuesta</div>
              <div className={styles.detail}>{latestOfferLine(summary.offers.latest)}</div>
            </SummaryCard>

            <SummaryCard
              icon="ti-search"
              title="Consultas"
              testId="card-queries"
              onClick={() => onNavigate('Comprando')}
            >
              <div className={styles.num}>{metricLabel(summary.queries.unanswered)}</div>
              <div className={styles.label}>sin respuesta</div>
              <div className={styles.detail}>{latestQueryLine(summary.queries.latest)}</div>
            </SummaryCard>

            <SummaryCard
              icon="ti-package"
              title="Inventario"
              testId="card-inventory"
              onClick={() => onNavigate('Inventario')}
            >
              <div className={styles.detail}>
                <b>{summary.inventory.published.toLocaleString('es-ES')}</b>{' '}
                <span>líneas publicadas</span>
              </div>
              <div className={styles.detail}>
                {`Última publicación: ${dateLabel(summary.inventory.lastUploadAt)}`}
              </div>
              <div className={styles.detail}>
                <b>{metricLabel(summary.inventory.visits)}</b> <span>visitas (30d)</span>
              </div>
            </SummaryCard>

            <SummaryCard
              icon="ti-messages"
              title="Hilos"
              testId="card-threads"
              onClick={() => onNavigate('Hilos')}
            >
              <div className={styles.num}>{metricLabel(summary.threads.unread)}</div>
              <div className={styles.label}>con mensajes sin leer</div>
              <div className={styles.detail}>{THREADS_UNAVAILABLE}</div>
            </SummaryCard>

            <SummaryCard
              icon="ti-circle-check"
              title="Resumen mes"
              testId="card-month"
              wide
              onClick={() => onNavigate('Vendiendo')}
            >
              <div className={styles.metricsRow}>
                <div className={styles.metric}>
                  <div className={styles.num}>
                    {summary.month.acceptedOffers.toLocaleString('es-ES')}
                  </div>
                  <div className={styles.label}>Ofertas Aceptadas</div>
                </div>
                <div className={styles.metric}>
                  <div className={styles.num}>
                    {summary.month.madeOffers.toLocaleString('es-ES')}
                  </div>
                  <div className={styles.label}>Ofertas Realizadas</div>
                </div>
                <div className={styles.metric}>
                  <div className={styles.num}>
                    {summary.month.receivedQueries.toLocaleString('es-ES')}
                  </div>
                  <div className={styles.label}>Consultas Realizadas</div>
                </div>
              </div>
            </SummaryCard>

            <SummaryCard
              icon="ti-star"
              title="Favoritos recibidos"
              testId="card-favorites"
              disabled
              disabledTitle={FAVORITES_DISABLED_TITLE}
            >
              <div className={styles.num}>{metricLabel(summary.favorites.monthly)}</div>
              <div className={styles.label}>organizaciones te añadieron a favoritos este mes</div>
            </SummaryCard>
          </div>
        )}
      </div>
    </div>
  );
}

interface SummaryCardProps {
  icon: string;
  title: string;
  children: ReactNode;
  wide?: boolean;
  onClick?: () => void;
  disabled?: boolean;
  disabledTitle?: string;
  testId?: string;
}

function SummaryCard({
  icon,
  title,
  children,
  wide,
  onClick,
  disabled,
  disabledTitle,
  testId,
}: SummaryCardProps) {
  return (
    <button
      type="button"
      className={`${styles.card} ${wide ? styles.wide : ''} ${disabled ? styles.disabled : ''}`}
      {...(onClick ? { onClick } : {})}
      {...(disabled ? { disabled: true } : {})}
      {...(disabled && disabledTitle ? { title: disabledTitle } : {})}
      {...(testId ? { 'data-testid': testId } : {})}
    >
      <div className={styles.cardHead}>
        <div className={styles.icon} aria-hidden="true">
          <i className={`ti ${icon}`} />
        </div>
        <div className={styles.cardTitle}>{title}</div>
      </div>
      {children}
    </button>
  );
}
